function outline(text, opts){
  opts=opts||{}; var max=opts.max!=null?opts.max:20; if(max<1)max=1; else if(max>200)max=200;
  var lines=text.replace(/\r/g,' ').split(/\n+/).map(function(s){return s.trim();}).filter(Boolean);
  var out=[];
  for(var i=0;i<lines.length && out.length<max;i++){ var s=lines[i]; out.push(/^#+\s/.test(s)? s : '- '+s); }
  return out.join('\n');
}

var EXPORTS={outline:outline};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.OutlineForgePure = EXPORTS; }
